const msg = "【时间提醒】已投入约40分钟，报告还没落盘。请立刻执行：\n\n1. **停止继续扩大抓取范围**，把手里已有的数据先写进报告文件\n2. 报告可以先用已有数据写，标注清楚样本量（比如「抓了5个站，其中3个有数据」）\n3. 剩下15分钟内必须完成：写报告 → git commit → push → 给我发总结\n\n宁可报告薄一点、诚实标注局限，也不要交白卷。有数据就写，没数据就写「未找到+为什么」。";

const results = [];
for (const t of ["student-overseas","student-domestic","student-verify"]) {
  try { const r = await tools.send_message({ target: t, message: msg }); results.push({t, sent: r.sent}); } catch(e) { results.push({t, err: String(e).slice(0,80)}); }
}
const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const now = Date.now();
const recent = [];
for (const f of await fs.readdir(S).catch(()=>[])) {
  try { const st = await fs.stat(S+"\\"+f); const age = (now-st.mtimeMs)/60000; if(age<20) recent.push(f); } catch {}
}
return { results, recentActivity: recent.length, sample: recent.slice(0,8) };
